public class MyBundleActivator implements BundleActivator {
    private ServiceTracker<MyService, MyService> serviceTracker;

    @Override
    public void start(BundleContext context) throws Exception {
        serviceTracker = new ServiceTracker<MyService, MyService>(
            context, 
            MyService.class, 
            new ServiceTrackerCustomizer<MyService, MyService>() {
                @Override
                public MyService addingService(ServiceReference<MyService> reference) {
                    MyService service = context.getService(reference);
                    // Service became available
                    handleServiceAdded(service);
                    return service;
                }

                @Override
                public void modifiedService(ServiceReference<MyService> reference, 
                                           MyService service) {
                    // Service properties changed
                    handleServiceModified(service);
                }

                @Override
                public void removedService(ServiceReference<MyService> reference, 
                                          MyService service) {
                    // Service going away
                    handleServiceRemoved(service);
                    context.ungetService(reference);
                }
            }
        );
        serviceTracker.open();
    }

    @Override
    public void stop(BundleContext context) throws Exception {
        if (serviceTracker != null) {
            serviceTracker.close();
        }
    }
}

@Component(
    service = MyService.class,
    configurationPolicy = ConfigurationPolicy.REQUIRE,
    property = {
        "service.vendor=IBM",
        "service.ranking:Integer=100"
    }
)
public class MyServiceImpl implements MyService {

    @Reference(cardinality = ReferenceCardinality.MULTIPLE,
               policy = ReferencePolicy.DYNAMIC)
    private volatile List<Plugin> plugins = new CopyOnWriteArrayList<>();

    @Reference
    private ConfigurationService configService;

    @Activate
    protected void activate(ComponentContext context, Map<String, Object> properties) {
        // Component activation
        String configValue = (String) properties.get("my.config.key");
        initialize(configValue);
    }

    @Modified
    protected void modified(Map<String, Object> properties) {
        // Configuration changed
        reconfigure(properties);
    }

    @Deactivate
    protected void deactivate() {
        // Cleanup
        shutdown();
    }

    // Dynamic reference methods
    protected void addPlugin(Plugin plugin) {
        plugins.add(plugin);
    }

    protected void removePlugin(Plugin plugin) {
        plugins.remove(plugin);
    }
}

@Component(service = ServiceConsumer.class)
public class ServiceConsumer {

    @Reference(
        target = "(service.type=premium)",
        cardinality = ReferenceCardinality.OPTIONAL
    )
    private volatile PremiumService premiumService;

    @Reference(
        target = "(&(service.type=standard)(service.region=us-east))"
    )
    private volatile StandardService standardService;

    public void processRequest(Request request) {
        if (premiumService != null && request.isPremium()) {
            premiumService.process(request);
        } else {
            standardService.process(request);
        }
    }
}

public class CustomInjectionExtension implements Extension {

    public void processInjectionPoints(@Observes ProcessInjectionPoint<?, ?> event) {
        InjectionPoint ip = event.getInjectionPoint();

        if (ip.getAnnotated().isAnnotationPresent(CustomInject.class)) {
            // Validate custom injection point
            validateCustomInjection(ip);
        }
    }

    public void afterBeanDiscovery(@Observes AfterBeanDiscovery event, 
                                   BeanManager beanManager) {
        // Add custom beans programmatically
        event.addBean()
            .types(CustomService.class)
            .scope(ApplicationScoped.class)
            .createWith(ctx -> createCustomService())
            .destroyWith((service, ctx) -> destroyCustomService(service));
    }

    public void afterDeploymentValidation(@Observes AfterDeploymentValidation event,
                                         BeanManager beanManager) {
        // Validate deployment
        Set<Bean<?>> beans = beanManager.getBeans(RequiredService.class);
        if (beans.isEmpty()) {
            event.addDeploymentProblem(
                new IllegalStateException("RequiredService not found")
            );
        }
    }
}

// Define qualifiers
@Qualifier
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.FIELD, ElementType.METHOD, ElementType.PARAMETER})
public @interface Database {
    DatabaseType value();
}

public enum DatabaseType {
    PRIMARY, SECONDARY, CACHE
}

// Producer methods
@ApplicationScoped
public class DataSourceProducer {

    @Produces
    @Database(DatabaseType.PRIMARY)
    @ApplicationScoped
    public DataSource createPrimaryDataSource() {
        return createDataSource("jdbc/primary");
    }

    @Produces
    @Database(DatabaseType.SECONDARY)
    @ApplicationScoped
    public DataSource createSecondaryDataSource() {
        return createDataSource("jdbc/secondary");
    }

    @Produces
    @Database(DatabaseType.CACHE)
    @ApplicationScoped
    public DataSource createCacheDataSource() {
        return createDataSource("jdbc/cache");
    }
}

// Injection
@ApplicationScoped
public class DataService {

    @Inject
    @Database(DatabaseType.PRIMARY)
    private DataSource primaryDb;

    @Inject
    @Database(DatabaseType.SECONDARY)
    private DataSource secondaryDb;
}

