// Interceptor binding
@InterceptorBinding
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.TYPE, ElementType.METHOD})
public @interface Audited {
    String value() default "";
}

// Interceptor implementation
@Audited
@Interceptor
@Priority(Interceptor.Priority.APPLICATION)
public class AuditInterceptor {

    @Inject
    private AuditService auditService;

    @AroundInvoke
    public Object audit(InvocationContext context) throws Exception {
        String methodName = context.getMethod().getName();
        String className = context.getTarget().getClass().getSimpleName();

        Audited annotation = context.getMethod().getAnnotation(Audited.class);
        String auditMessage = annotation.value().isEmpty() 
            ? methodName 
            : annotation.value();

        long startTime = System.currentTimeMillis();
        try {
            Object result = context.proceed();
            long duration = System.currentTimeMillis() - startTime;

            auditService.logSuccess(className, auditMessage, duration);
            return result;
        } catch (Exception e) {
            auditService.logFailure(className, auditMessage, e);
            throw e;
        }
    }
}

