    }
}

// Authentication filter
@Provider
@Priority(Priorities.AUTHENTICATION)
public class AuthenticationFilter implements ContainerRequestFilter {

    @Inject
    private TokenValidator tokenValidator;

    @Override
    public void filter(ContainerRequestContext requestContext) {
        String authHeader = requestContext.getHeaderString(HttpHeaders.AUTHORIZATION);

        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            requestContext.abortWith(
                Response.status(Status.UNAUTHORIZED)
                    .entity("Missing or invalid authorization header")
                    .build()
            );
            return;
        }

        String token = authHeader.substring("Bearer ".length());
        try {
            UserPrincipal principal = tokenValidator.validate(token);
            SecurityContext securityContext = new CustomSecurityContext(principal);
            requestContext.setSecurityContext(securityContext);
        } catch (TokenValidationException e) {
            requestContext.abortWith(
                Response.status(Status.UNAUTHORIZED)
                    .entity("Invalid token")
                    .build()
            );
        }
    }
}

// Authorization filter
@Provider
@Priority(Priorities.AUTHORIZATION)
public class AuthorizationFilter implements ContainerRequestFilter {

    @Override
    public void filter(ContainerRequestContext requestContext) {
        SecurityContext securityContext = requestContext.getSecurityContext();

        if (securityContext == null || securityContext.getUserPrincipal() == null) {
            requestContext.abortWith(
                Response.status(Status.FORBIDDEN)
                    .entity("Authentication required")
                    .build()
            );
            return;
        }

        // Check method-level security annotations
        ResourceInfo resourceInfo = getResourceInfo(requestContext);
        RolesAllowed rolesAllowed = resourceInfo.getResourceMethod()
            .getAnnotation(RolesAllowed.class);

        if (rolesAllowed != null) {
            boolean authorized = Arrays.stream(rolesAllowed.value())
                .anyMatch(securityContext::isUserInRole);

            if (!authorized) {
                requestContext.abortWith(
                    Response.status(Status.FORBIDDEN)
                        .entity("Insufficient permissions")
                        .build()
                );
            }
        }
    }
}

// Custom security context
public class CustomSecurityContext implements SecurityContext {
    private final UserPrincipal principal;

    public CustomSecurityContext(UserPrincipal principal) {
        this.principal = principal;
    }

    @Override
    public Principal getUserPrincipal() {
        return principal;
    }

    @Override
    public boolean isUserInRole(String role) {
        return principal.getRoles().contains(role);
    }

    @Override
    public boolean isSecure() {
        return true;
    }

    @Override
    public String getAuthenticationScheme() {
        return "Bearer";
    }
}

// Base exception mapper
@Provider
public class BaseExceptionMapper implements ExceptionMapper<Exception> {

    @Inject
    private Logger logger;

    @Override
    public Response toResponse(Exception exception) {
        logger.error("Unhandled exception", exception);

        ErrorResponse error = new ErrorResponse(
            "INTERNAL_ERROR",
            "An unexpected error occurred",
            null
        );

        return Response.status(Status.INTERNAL_SERVER_ERROR)
                      .entity(error)
                      .build();
    }
}

// Validation exception mapper
@Provider
public class ValidationExceptionMapper 
    implements ExceptionMapper<ConstraintViolationException> {

    @Override
    public Response toResponse(ConstraintViolationException exception) {
        List<String> violations = exception.getConstraintViolations().stream()
            .map(v -> v.getPropertyPath() + ": " + v.getMessage())
            .collect(Collectors.toList());

        ErrorResponse error = new ErrorResponse(
            "VALIDATION_ERROR",
            "Request validation failed",
            violations
        );

        return Response.status(Status.BAD_REQUEST)
                      .entity(error)
                      .build();
    }
}

// Business exception mapper
@Provider
public class BusinessExceptionMapper implements ExceptionMapper<BusinessException> {

    @Override
    public Response toResponse(BusinessException exception) {
        ErrorResponse error = new ErrorResponse(
            exception.getErrorCode(),
            exception.getMessage(),
            exception.getDetails()
        );

        Status status = mapToHttpStatus(exception.getErrorCode());

        return Response.status(status)
                      .entity(error)
                      .build();
    }

    private Status mapToHttpStatus(String errorCode) {
        switch (errorCode) {
            case "NOT_FOUND": return Status.NOT_FOUND;
            case "CONFLICT": return Status.CONFLICT;
            case "FORBIDDEN": return Status.FORBIDDEN;
            default: return Status.BAD_REQUEST;
        }
    }
}

