    public ErrorResponse(String code, String message, List<String> details) {
        this.code = code;
        this.message = message;
        this.details = details;
        this.timestamp = Instant.now();
    }

    // Getters and setters
}

@Path("/async")
@RequestScoped
public class AsyncResource {

    @Inject
    private ManagedExecutorService executor;

    @Inject
    private LongRunningService service;

    @GET
    @Path("/process/{id}")
    @Produces(MediaType.APPLICATION_JSON)
    public void processAsync(@PathParam("id") String id,
                            @Suspended AsyncResponse response) {

        // Set timeout
        response.setTimeout(30, TimeUnit.SECONDS);

        // Set timeout handler
        response.setTimeoutHandler(asyncResponse -> {
            ErrorResponse error = new ErrorResponse(
                "TIMEOUT",
                "Request processing timed out",
                null
            );
            asyncResponse.resume(
                Response.status(Status.SERVICE_UNAVAILABLE)
                    .entity(error)
                    .build()
            );
        });

        // Process asynchronously
        executor.submit(() -> {
            try {
                Result result = service.process(id);
                response.resume(Response.ok(result).build());
            } catch (BusinessException e) {
                response.resume(e);
            } catch (Exception e) {
                ErrorResponse error = new ErrorResponse(
                    "PROCESSING_ERROR",
                    "Failed to process request",
                    null
                );
                response.resume(
                    Response.status(Status.INTERNAL_SERVER_ERROR)
                        .entity(error)
                        .build()
                );
            }
        });
    }

    @POST
    @Path("/batch")
    @Produces(MediaType.APPLICATION_JSON)
    public CompletionStage<Response> processBatch(List<Request> requests) {
        return CompletableFuture.supplyAsync(() -> {
            List<Result> results = requests.stream()
                .map(service::process)
                .collect(Collectors.toList());

            return Response.ok(results).build();
        }, executor);
    }
}

