public class DatabaseConfig {
    private String url;
    private String username;
    private int maxConnections;

    // Constructor, getters, setters
}

// Converter
public class DatabaseConfigConverter implements Converter<DatabaseConfig> {

    @Override
    public DatabaseConfig convert(String value) {
        // Parse JSON or custom format
        // Example: "url=jdbc:...,username=admin,maxConnections=10"
        Map<String, String> props = parseProperties(value);

        DatabaseConfig config = new DatabaseConfig();
        config.setUrl(props.get("url"));
        config.setUsername(props.get("username"));
        config.setMaxConnections(Integer.parseInt(props.get("maxConnections")));

        return config;
    }
}

