// Liveness check
@Liveness
@ApplicationScoped
public class ApplicationLivenessCheck implements HealthCheck {

    @Inject
    private ApplicationState appState;

    @Override
    public HealthCheckResponse call() {
        boolean isAlive = !appState.isDeadlocked() && !appState.isShuttingDown();

        return HealthCheckResponse.named("application-liveness")
            .status(isAlive)
            .withData("uptime", appState.getUptimeSeconds())
            .withData("threads", Thread.activeCount())
            .build();
    }
}

// Readiness check
@Readiness
@ApplicationScoped
public class ApplicationReadinessCheck implements HealthCheck {

    @Inject
    private DataSource dataSource;

    @Inject
    private CacheService cacheService;

    @Override
    public HealthCheckResponse call() {
        HealthCheckResponseBuilder builder = HealthCheckResponse
            .named("application-readiness");

        boolean ready = true;

        // Check database
        try (Connection conn = dataSource.getConnection()) {
            builder.withData("database", "UP");
        } catch (SQLException e) {
            builder.withData("database", "DOWN: " + e.getMessage());
            ready = false;
        }

        // Check cache
        if (cacheService.isAvailable()) {
            builder.withData("cache", "UP");
        } else {
            builder.withData("cache", "DOWN");
            ready = false;
        }

        return builder.status(ready).build();
    }
}

// Startup check
@Startup
@ApplicationScoped
public class ApplicationStartupCheck implements HealthCheck {

    @Inject
    private InitializationService initService;

    @Override
    public HealthCheckResponse call() {
        boolean initialized = initService.isInitialized();

        return HealthCheckResponse.named("application-startup")
            .status(initialized)
            .withData("initialization-time", initService.getInitTimeMs())
            .build();
    }
}

@ApplicationScoped
public class OrderService {

    @Inject
    @Metric(name = "orders_created_total", absolute = true)
    private Counter ordersCreated;

    @Inject
    @Metric(name = "order_processing_time", absolute = true)
    private Timer processingTime;

    @Inject
    private MetricRegistry registry;

    @PostConstruct
    public void init() {
        // Register custom metrics with tags
        registry.counter(
            Metadata.builder()
                .withName("orders_by_status")
                .withDescription("Number of orders by status")
                .withType(MetricType.COUNTER)
                .build(),
            new Tag("status", "pending")
        );
    }

    public Order createOrder(OrderRequest request) {
        Timer.Context context = processingTime.time();
        try {
            Order order = processOrder(request);
            ordersCreated.inc();

            // Update status-specific counter
            Counter statusCounter = registry.counter(
                "orders_by_status",
                new Tag("status", order.getStatus())
            );
            statusCounter.inc();

            return order;
        } finally {
            context.stop();
        }
    }

    @Gauge(name = "active_orders", unit = MetricUnits.NONE, absolute = true)
    public long getActiveOrderCount() {
        return countActiveOrders();
    }
}

@ApplicationScoped
public class ExternalServiceClient {

    @Inject
    private RestClient restClient;

    @Inject
    private CacheService cache;

    @Retry(
        maxRetries = 3,
        delay = 1000,
        delayUnit = ChronoUnit.MILLIS,
        jitter = 200,
        retryOn = {ServiceUnavailableException.class, TimeoutException.class}
    )
    @Timeout(value = 5, unit = ChronoUnit.SECONDS)
    @CircuitBreaker(
        requestVolumeThreshold = 10,
        failureRatio = 0.5,
        delay = 10000,
        successThreshold = 3
    )
    @Fallback(fallbackMethod = "getDataFromCache")
    @Bulkhead(value = 10, waitingTaskQueue = 20)
    public Data fetchData(String id) {
        return restClient.getData(id);
    }

    public Data getDataFromCache(String id) {
        Data cached = cache.get(id);
        if (cached != null) {
            return cached;
        }
        throw new DataNotFoundException("Data not available: " + id);
    }

    // Async with fault tolerance
    @Asynchronous
    @Retry(maxRetries = 2)
    @Timeout(value = 10, unit = ChronoUnit.SECONDS)
    public CompletionStage<List<Data>> fetchMultipleData(List<String> ids) {
        return CompletableFuture.supplyAsync(() -> 
            ids.stream()
                .map(this::fetchData)
                .collect(Collectors.toList())
        );
    }
}

// CDI-enabled JAX-RS resource
@Path("/users")
@RequestScoped
public class UserResource {

    @Inject
    private UserService userService;

    @Inject
    private SecurityContext securityContext;

    @Context
    private UriInfo uriInfo;

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response listUsers(@QueryParam("page") @DefaultValue("0") int page,
                             @QueryParam("size") @DefaultValue("20") int size) {
        List<User> users = userService.findAll(page, size);
        return Response.ok(users).build();
    }
}

// CDI extension for RESTeasy integration
public class ResteasyIntegrationExtension implements Extension {

    public void processAnnotatedType(@Observes ProcessAnnotatedType<?> event) {
        AnnotatedType<?> type = event.getAnnotatedType();

        // Ensure JAX-RS resources are CDI beans
        if (type.isAnnotationPresent(Path.class)) {
            if (!hasScope(type)) {
                // Add @RequestScoped if no scope defined
                event.configureAnnotatedType()
                    .add(RequestScoped.Literal.INSTANCE);
            }
        }
    }
}

// Feature bundle activator
public class MyFeatureActivator implements BundleActivator {

    private ServiceRegistration<?> registration;

    @Override
    public void start(BundleContext context) throws Exception {
        // Wait for required services
        ServiceTracker<ServletContainerInitializer, ServletContainerInitializer> tracker =
            new ServiceTracker<>(context, ServletContainerInitializer.class, null);
        tracker.open();

        // Register feature service
        Dictionary<String, Object> props = new Hashtable<>();
        props.put("service.vendor", "IBM");
        props.put("feature.name", "myFeature-1.0");

        registration = context.registerService(
            MyFeatureService.class.getName(),
            new MyFeatureServiceImpl(),
            props
        );
    }

    @Override
    public void stop(BundleContext context) throws Exception {
        if (registration != null) {
            registration.unregister();
        }
    }
}

